import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0043: Proofs as First-Class Values","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/0043-proofs-as-first-class-values.md","filePath":"vendored/handl/project/adrs/0043-proofs-as-first-class-values.md"}`),a={name:`handl/project/adrs/0043-proofs-as-first-class-values.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0043-proofs-as-first-class-values" tabindex="-1">ADR-0043: Proofs as First-Class Values <a class="header-anchor" href="#adr-0043-proofs-as-first-class-values" aria-label="Permalink to “ADR-0043: Proofs as First-Class Values”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>Proposed</p><p>Builds on <a href="./0042-transformations-as-first-class-values.html">ADR-0042 — Transformations as First-Class Values</a>.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>ADR-0041 made <code>Language</code> a first-class value. ADR-0042 made transformations <code>Language -&gt; Language</code> first-class values. The next operator up is the one that operates on transformations: <strong>the claim that a transformation is correct</strong> — that <code>compile(L, &quot;wasm&quot;)</code> preserves L&#39;s semantics, that <code>optimize</code> is semantics-preserving, that a translator <code>A -&gt; B</code> faithfully translates.</p><p>Today that claim is a theorem you prove offline — in Coq, on paper, or not at all. The proof lives outside the program. The runtime trusts the toolchain because it cannot see the proof.</p><p>Once transformations are values, the proof &quot;this transformation preserves semantics&quot; is a value too. The operator that worked on level N becomes a value at level N+1, again:</p><table tabindex="0"><thead><tr><th>level</th><th>what&#39;s first-class</th><th>the operator</th></tr></thead><tbody><tr><td>1</td><td>functions</td><td><code>apply : (A -&gt; B) -&gt; A -&gt; B</code></td></tr><tr><td>2</td><td>languages</td><td><code>eval : Language -&gt; Source -&gt; Value</code></td></tr><tr><td>3</td><td>transformations</td><td><code>compose : (L -&gt; L) -&gt; (L -&gt; L) -&gt; (L -&gt; L)</code></td></tr><tr><td>4</td><td>proofs</td><td><code>verify : Proof -&gt; Bool</code></td></tr></tbody></table><p>A proof stops being a paper artifact and becomes a value you bind, pass, check, and compose. Compiler correctness stops being &quot;trust the toolchain&quot; and becomes &quot;verify the value.&quot;</p><h3 id="why-this-is-proof-carrying-code-at-the-language-level" tabindex="-1">Why this is proof-carrying code, at the language level <a class="header-anchor" href="#why-this-is-proof-carrying-code-at-the-language-level" aria-label="Permalink to “Why this is proof-carrying code, at the language level”">​</a></h3><p>Proof-carrying code (Necula, 1997) attaches a proof to compiled code so a verifier can check safety before running it. PCC is usually framed at the instruction level — a proof that this binary doesn&#39;t violate memory safety. This ADR lifts the same idea to the language level: a proof that this <code>Language -&gt; Language</code> transformation preserves semantics. The compiled artifact ships with its correctness proof as a value; the runtime checks the proof before applying the transformation.</p><p>The difference from classical PCC: the proof is a first-class handl value, not an external certificate. It can be composed, transformed, and reasoned about in-program, the same way languages and transformations can.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Make proofs first-class handl values. A proof is a value that attests to a property of a transformation. The runtime verifies proofs before applying the transformations they certify.</p><h3 id="_1-proofs-are-handl-values" tabindex="-1">1. Proofs are handl values <a class="header-anchor" href="#_1-proofs-are-handl-values" aria-label="Permalink to “1. Proofs are handl values”">​</a></h3><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span># a proof is a value: Transformation -&gt; Proof</span></span>
<span class="line"><span>correct: type.any = (t: type.any) -&gt; prove-preserves-semantics(t);</span></span>
<span class="line"><span></span></span>
<span class="line"><span># prove that a specific compiler is semantics-preserving</span></span>
<span class="line"><span>wasm-compiler: type.any = to-wasm(handl);</span></span>
<span class="line"><span>wasm-proof:    type.any = correct(wasm-compiler);    # a proof value</span></span></code></pre></div><p>The proof is constructed (offline, by a solver, or by a human) and then carried as a value alongside the transformation it certifies.</p><h3 id="_2-verification-is-a-runtime-check" tabindex="-1">2. Verification is a runtime check <a class="header-anchor" href="#_2-verification-is-a-runtime-check" aria-label="Permalink to “2. Verification is a runtime check”">​</a></h3><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span># compiler correctness becomes a runtime check, not a paper theorem</span></span>
<span class="line"><span>safe-compile: type.any = (l: type.any) -&gt; {</span></span>
<span class="line"><span>  t: type.any = to-wasm(l);</span></span>
<span class="line"><span>  p: type.any = correct(t);</span></span>
<span class="line"><span>  if verify(p) then apply(t, l) else reject</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>The runtime checks the proof value before applying the transformation. No trust in the toolchain; only trust in the verifier (which is small and fixed, the way a typechecker is small and fixed).</p><h3 id="_3-proofs-compose-with-transformations" tabindex="-1">3. Proofs compose with transformations <a class="header-anchor" href="#_3-proofs-compose-with-transformations" aria-label="Permalink to “3. Proofs compose with transformations”">​</a></h3><p>If <code>p1</code> proves <code>t1</code> correct and <code>p2</code> proves <code>t2</code> correct, then <code>compose-proofs(p1, p2)</code> proves <code>compose(t1, t2)</code> correct — provided the notion of correctness is compositional (semantics preservation is).</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span># compose transformations and their proofs together</span></span>
<span class="line"><span>pipeline: type.any = compose(optimize, strip-io);</span></span>
<span class="line"><span>proof:   type.any = compose-proofs(proof-optimize, proof-strip-io);</span></span>
<span class="line"><span></span></span>
<span class="line"><span># the composed pipeline is certified by the composed proof</span></span>
<span class="line"><span>if verify(proof) then apply(pipeline, handl) else reject;</span></span></code></pre></div><p>Proof composition mirrors transformation composition. A compiler pipeline ships with a composed proof, and the runtime verifies the composed proof once, not each pass individually.</p><h3 id="_4-certified-compilation" tabindex="-1">4. Certified compilation <a class="header-anchor" href="#_4-certified-compilation" aria-label="Permalink to “4. Certified compilation”">​</a></h3><p>A compiler ships as a pair: <code>(transformation, proof)</code>. The runtime verifies the proof before running the compiler. This is proof-carrying code at the language level.</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span># a certified compiler is a value: (Transformation, Proof)</span></span>
<span class="line"><span>certified-wasm: type.any = {</span></span>
<span class="line"><span>  transform: to-wasm,</span></span>
<span class="line"><span>  proof:     correct(to-wasm),</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span># the runtime verifies before applying</span></span>
<span class="line"><span>run-certified: type.any = (cert: type.any, l: type.any) -&gt; {</span></span>
<span class="line"><span>  if verify(cert.proof) then apply(cert.transform, l) else reject</span></span>
<span class="line"><span>};</span></span></code></pre></div><h3 id="_5-verified-interop" tabindex="-1">5. Verified interop <a class="header-anchor" href="#_5-verified-interop" aria-label="Permalink to “5. Verified interop”">​</a></h3><p>A translator <code>A -&gt; B</code> ships with a proof that it faithfully translates. Polyglot interop stops being &quot;trust the bridge&quot; and becomes &quot;verify the translator.&quot;</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>json-to-handl-cert: type.any = {</span></span>
<span class="line"><span>  transform: json-to-handl,</span></span>
<span class="line"><span>  proof:     prove-faithful(json-to-handl),</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span># verified translation at runtime</span></span>
<span class="line"><span>if verify(json-to-handl-cert.proof) then</span></span>
<span class="line"><span>  eval(handl, translate(json-to-handl-cert.transform, json-src))</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>  reject;</span></span></code></pre></div><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to “Positive”">​</a></h3><ul><li><strong>Compiler correctness becomes a runtime check.</strong> A compiler ships with its proof; the runtime verifies before running. No trust in the toolchain, only trust in the small fixed verifier.</li><li><strong>Proofs compose with transformations.</strong> A pipeline&#39;s proof is the composition of its passes&#39; proofs. Verify once, not per pass.</li><li><strong>Certified compilation.</strong> A compiler is a <code>(transformation, proof)</code> pair. This is proof-carrying code at the language level.</li><li><strong>Verified interop.</strong> A translator ships with a faithfulness proof. Polyglot interop is verified, not trusted.</li><li><strong>The tower is uniform.</strong> Proofs are values in a language, transformations are functions in a language, languages are evaluated by <code>eval</code>, functions are applied by <code>apply</code>. No privileged meta-level. Level 4 bottoms out at level 1, the way level 3 did at level 2.</li><li><strong>Auditable supply chain.</strong> A language or compiler shipped as a value carries its proof of correctness. The consumer verifies before use. No more &quot;trust the binary.&quot;</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to “Negative”">​</a></h3><ul><li><strong>Proof construction is hard.</strong> Generating proofs for nontrivial transformations is the open problem of automated theorem proving. Interactive theorem provers (Coq, Lean) work but require human effort. SMT-based approaches scale but only for restricted property languages. This ADR does not solve proof construction; it makes proofs <em>first-class</em> so that whatever construction method is used (manual, automated, or hybrid) produces a value the runtime can check.</li><li><strong>The verifier must be trusted.</strong> The runtime checks proofs against a verifier. That verifier is now the trusted computing base, the way a typechecker is. It must be small, fixed, and audited. This is the same trust reduction as proof-carrying code: trust a small verifier instead of a large toolchain.</li><li><strong>Compositional correctness is not free.</strong> Proof composition requires that the notion of correctness is compositional. Semantics preservation is (under conditions), but not every property is. The framework must track which proofs compose and which do not.</li><li><strong>Nobody has shipped this in a production language.</strong> Proof-carrying code exists at the instruction level (Necula, 1997; Typed Assembly Language). Certified compilation exists in research compilers (CompCert, CakeML). First-class proofs as runtime values in a general-purpose language is uncharted. This is the research frontier, one level above the research frontier of ADR-0041.</li><li><strong>Performance.</strong> Proof verification at load time has a cost. For large proofs (which nontrivial transformations produce), this is non-trivial. Caching verified proofs mitigates, but the first load pays.</li></ul><h2 id="the-full-tower" tabindex="-1">The full tower <a class="header-anchor" href="#the-full-tower" aria-label="Permalink to “The full tower”">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>What&#39;s first-class</th><th>The operator</th><th>What it unlocks</th></tr></thead><tbody><tr><td>0</td><td>Data</td><td>—</td><td>Values</td></tr><tr><td>1</td><td>Functions</td><td><code>apply</code></td><td>Recursion, Turing completeness</td></tr><tr><td>2</td><td>Languages</td><td><code>eval</code></td><td>Universal host, self-bootstrap</td></tr><tr><td>3</td><td>Transformations</td><td><code>compose</code></td><td>Composable compilers, category of languages</td></tr><tr><td>4</td><td>Proofs</td><td><code>verify</code></td><td>Certified compilation, verified interop</td></tr></tbody></table><p>Each level makes the operator of the previous level a value. Each level is the same move. Each level bottoms out at the one below — proofs are values in a language, transformations are functions in a language, languages are evaluated by <code>eval</code>, functions are applied by <code>apply</code>. The tower is uniform; there is no privileged meta-level.</p><h2 id="implementation-phases" tabindex="-1">Implementation phases <a class="header-anchor" href="#implementation-phases" aria-label="Permalink to “Implementation phases”">​</a></h2><h3 id="phase-1-—-define-the-proof-value-type" tabindex="-1">Phase 1 — Define the proof value type <a class="header-anchor" href="#phase-1-—-define-the-proof-value-type" aria-label="Permalink to “Phase 1 — Define the proof value type”">​</a></h3><p>A <code>Proof</code> is a handl value attesting to a property of a transformation. The exact encoding (dependent types, refinement types, explicit certificate) is deferred to implementation. The contract is: <code>verify : Proof -&gt; Bool</code> is a small, fixed, audited function.</p><h3 id="phase-2-—-verify-before-apply" tabindex="-1">Phase 2 — Verify before apply <a class="header-anchor" href="#phase-2-—-verify-before-apply" aria-label="Permalink to “Phase 2 — Verify before apply”">​</a></h3><p>The runtime checks <code>verify(proof)</code> before applying a certified transformation. Unverified transformations are allowed but flagged (unlike ADR-0041&#39;s <code>eval</code>, <code>apply</code> of a transformation <em>can</em> be gated, because transformations are not plumbing — they are the thing with authority over the result language&#39;s semantics).</p><h3 id="phase-3-—-proof-composition" tabindex="-1">Phase 3 — Proof composition <a class="header-anchor" href="#phase-3-—-proof-composition" aria-label="Permalink to “Phase 3 — Proof composition”">​</a></h3><p><code>compose-proofs : Proof -&gt; Proof -&gt; Proof</code> mirrors <code>compose</code> for transformations, for compositional properties (semantics preservation).</p><h3 id="phase-4-—-certified-compilers-and-translators" tabindex="-1">Phase 4 — Certified compilers and translators <a class="header-anchor" href="#phase-4-—-certified-compilers-and-translators" aria-label="Permalink to “Phase 4 — Certified compilers and translators”">​</a></h3><p>Ship <code>(transformation, proof)</code> pairs for the standard transformations (<code>compile</code>, <code>optimize</code>, <code>restrict</code>, translators). The runtime verifies before applying.</p><h3 id="phase-5-—-proof-construction-tooling" tabindex="-1">Phase 5 — Proof construction tooling <a class="header-anchor" href="#phase-5-—-proof-construction-tooling" aria-label="Permalink to “Phase 5 — Proof construction tooling”">​</a></h3><p>Tooling to construct proofs — interactive, SMT-based, or hybrid. This is the hardest phase and the most open. The ADR does not mandate a specific method; it mandates that whatever method is used produces a first-class <code>Proof</code> value the runtime can check.</p><h2 id="related-work" tabindex="-1">Related work <a class="header-anchor" href="#related-work" aria-label="Permalink to “Related work”">​</a></h2><ul><li><a href="./0041-languages-as-first-class-values.html">ADR-0041</a> — Languages as First-Class Values</li><li><a href="./0042-transformations-as-first-class-values.html">ADR-0042</a> — Transformations as First-Class Values (this ADR certifies those transformations)</li><li>Proof-carrying code (Necula, 1997) — proofs attached to compiled code, verified before execution; this ADR lifts the idea to the language level</li><li>CompCert — certified C compiler (Leroy et al.); offline proof, not a runtime value</li><li>CakeML — verified ML compiler; offline proof, not a runtime value</li><li>Typed Assembly Language — types as proofs at the instruction level</li><li>Refinement types (LiquidHaskell, F*) — proofs as types, in-language</li><li>3-Lisp — reflective tower; this ADR is the proof level of the tower</li></ul>`,52)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};